interface WorkRow { id: string; input: string; steps: number; fail_attempts: number; attempts: number }
async function processJob(job: WorkRow): Promise<void> {
  // A crash recovery still consumes an attempt. Do not start a fourth attempt.
  if (job.attempts > 3) {
    db.prepare("UPDATE jobs SET status='failed', error='transient failure', result=NULL, updated_at=? WHERE id=? AND status='running'").run(new Date().toISOString(), job.id);
    return;
  }
  if (job.attempts <= job.fail_attempts) {
    // Simulated dependency failures happen before the first unit of progress.
    await sleep(100);
    const now = new Date().toISOString();
    if (job.attempts >= 3) {
      db.prepare("UPDATE jobs SET status='failed', error='transient failure', result=NULL, progress_completed=0, updated_at=? WHERE id=? AND status='running'").run(now, job.id);
    } else {
      db.prepare("UPDATE jobs SET status='queued', error=NULL, result=NULL, progress_completed=0, available_at=?, updated_at=? WHERE id=? AND status='running'").run(Date.now() + 500, now, job.id);
    }
    return;
  }
  for (let i = 1; i <= job.steps; i++) {
    await sleep(100);
    db.prepare("UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running'").run(i, new Date().toISOString(), job.id);
  }
  db.prepare("UPDATE jobs SET status='completed', result=?, error=NULL, progress_completed=steps, updated_at=? WHERE id=? AND status='running'")
    .run(JSON.stringify({ output: job.input.toUpperCase() }), new Date().toISOString(), job.id);
}

console.log('worker started');
try {
  while (!stopping) {
    let job: WorkRow | undefined;
    db.exec('BEGIN IMMEDIATE');
    try {
      const candidate = db.prepare("SELECT id,input,steps,fail_attempts,attempts FROM jobs WHERE status='queued' AND available_at<=? ORDER BY created_at,rowid LIMIT 1").get(Date.now()) as WorkRow | undefined;
      if (candidate) {
        if (candidate.attempts >= 3) {
          db.prepare("UPDATE jobs SET status='failed', error='transient failure', result=NULL, updated_at=? WHERE id=? AND status='queued'").run(new Date().toISOString(), candidate.id);
        } else {
          const updated = db.prepare("UPDATE jobs SET status='running', attempts=attempts+1, progress_completed=0, updated_at=? WHERE id=? AND status='queued'").run(new Date().toISOString(), candidate.id);
          if (Number(updated.changes) > 0) job = { ...candidate, attempts: candidate.attempts + 1 };
        }
      }
      db.exec('COMMIT');
    } catch (e) { db.exec('ROLLBACK'); throw e; }
    if (job) {
      try { await processJob(job); }
      catch (e) {
        console.error('job processing failed', e);
        db.prepare("UPDATE jobs SET status=CASE WHEN attempts>=3 THEN 'failed' ELSE 'queued' END, error=CASE WHEN attempts>=3 THEN 'transient failure' ELSE NULL END, available_at=?, updated_at=? WHERE id=? AND status='running'")
          .run(Date.now() + 500, new Date().toISOString(), job.id);
      }
    } else await sleep(100);
  }
} finally {
  clearInterval(beatTimer);
  db.close();
}
