<body>
  <h1>Job tracker</h1>
  <p class="intro">Submit text and follow its progress as the worker processes it.</p>
  <form data-testid="job-form" id="job-form">
    <label>Input
      <input data-testid="job-input" name="input" type="text" maxlength="1000" required>
    </label>
    <label>Steps
      <input data-testid="job-steps" name="steps" type="number" min="1" max="20" value="5" required>
    </label>
    <label>Fail attempts
      <input data-testid="job-fail-attempts" name="failAttempts" type="number" min="0" max="5" value="0" required>
    </label>
    <button data-testid="job-submit" type="submit">Submit job</button>
    <div data-testid="form-error" id="form-error" role="alert"></div>
  </form>
  <h2>Jobs</h2>
  <ul data-testid="job-list" id="job-list" aria-live="polite"></ul>
  <script>
    const form = document.querySelector('[data-testid="job-form"]');
    const errorRegion = document.querySelector('[data-testid="form-error"]');
    const list = document.querySelector('[data-testid="job-list"]');
    function showError(data) {
      const error = data?.error;
      if (!error) { errorRegion.textContent = 'The request could not be submitted.'; return; }
      const fields = Array.isArray(error.fields) ? error.fields.map(item => `${item.field}: ${item.message}`) : [];
      errorRegion.textContent = [error.message, ...fields].join(' ');
    }
    function render(jobs) {
      list.replaceChildren(...jobs.map(job => {
        const item = document.createElement('li');
        item.className = 'job'; item.dataset.testid = 'job-item'; item.dataset.jobId = job.id;
        const header = document.createElement('header');
        const status = document.createElement('strong'); status.dataset.testid = 'job-status'; status.textContent = job.status;
        const progress = document.createElement('span'); progress.dataset.testid = 'job-progress'; progress.textContent = `${job.progress.completed}/${job.progress.total}`;
        header.append(status, progress);
        const input = document.createElement('p'); input.textContent = job.input;
        const result = document.createElement('p'); result.dataset.testid = 'job-result'; result.className = 'job-result';
        result.textContent = job.result?.output ?? job.error ?? '';
        const id = document.createElement('code'); id.textContent = job.id;
        item.append(header, input, result, id); return item;
      }));
    }
    async function refresh() {
      try { const response = await fetch('/api/jobs'); if (response.ok) render((await response.json()).jobs); } catch { /* retry on next poll */ }
    }
    form.addEventListener('submit', async event => {
      event.preventDefault(); errorRegion.textContent = '';
      const data = new FormData(form);
      const payload = { input: data.get('input'), steps: Number(data.get('steps')), failAttempts: Number(data.get('failAttempts')) };
      try {
        const response = await fetch('/api/jobs', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
        if (!response.ok) showError(await response.json()); else { form.elements.input.value = ''; await refresh(); }
      } catch { errorRegion.textContent = 'Could not reach the server.'; }
    });
    refresh(); setInterval(refresh, 700);
  </script>
</body>
